/**
 * @param {string} word
 * @return {number}
 */
var numberOfSpecialChars = function(word) {
    const map = new Map();

    for (let i = 0; i < word.length; i++) {
        if (!map.has(word[i])) {
            map.set(word[i], []);
        }
        map.get(word[i]).push(i);
    }

    let res = 0;

    for (let i = 0; i < 26; i++) {
        const char = String.fromCharCode(97 + i);
        const upChar = String.fromCharCode(65 + i);

        const charArr = map.get(char) || [];
        const upCharArr = map.get(upChar) || [];

        if (charArr.length > 0 && upCharArr.length > 0 && charArr[charArr.length - 1] < upCharArr[0]) {
            res++;
        }
    }

    return res;
};

